files.content:
:root {
  --bg: #1a1c2c;
  --card: #2d2f45;
  --accent: #ffcd75;
  --text: #f4f4f4;
  --danger: #ff6b6b;
  --border: #4a4e69;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: 'Courier New', monospace;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 #0f111a;
  padding: 24px;
  width: 100%;
  max-width: 480px;
}

h1 {
  font-size: 24px;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent);
  text-align: center;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

#todo-input {
  flex: 1;
  padding: 12px;
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  font-family: inherit;
  font-size: 16px;
  outline: none;
}

#todo-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 205, 117, 0.3);
}

#todo-add {
  padding: 12px 20px;
  background: var(--accent);
  border: 3px solid var(--border);
  color: var(--bg);
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
  text-transform: uppercase;
  box-shadow: 4px 4px 0 #0f111a;
  transition: transform 0.1s, box-shadow 0.1s;
}

#todo-add:hover {
  background: #ffe08a;
}

#todo-add:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #0f111a;
}

#todo-add:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.counts {
  display: flex;
  justify-content: space-between;
  margin-bottom: 16px;
  font-size: 16px;
  color: var(--accent);
  border-bottom: 2px dashed var(--border);
  padding-bottom: 8px;
}

#todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  background: var(--bg);
  border: 2px solid var(--border);
}

.task-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}

.task-item input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.task-item span {
  flex: 1;
  word-break: break-word;
  font-size: 16px;
}

.task-item input[type="checkbox"]:checked + span {
  text-decoration: line-through;
  opacity: 0.6;
}

.task-item button {
  padding: 6px 10px;
  background: var(--danger);
  border: 2px solid var(--border);
  color: var(--text);
  font-family: inherit;
  font-size: 16px;
  cursor: pointer;
  box-shadow: 3px 3px 0 #0f111a;
  transition: transform 0.1s, box-shadow 0.1s;
  flex-shrink: 0;
}

.task-item button:hover {
  background: #ff8a8a;
}

.task-item button:active {
  transform: translate(1px, 1px);
  box-shadow: 2px 2px 0 #0f111a;
}

.task-item button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .input-row {
    flex-direction: column;
  }
  #todo-add {
    width: 100%;
  }
}

let tasks = [];
let nextId = 1;

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.completed).length;
}

function createTaskElement(task) {
  const li = document.createElement('li');
  li.className = 'task-item';

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = `todo-check-${task.id}`;
  checkbox.checked = task.completed;
  checkbox.setAttribute('aria-label', `Mark "${task.text}" as completed`);
  checkbox.addEventListener('change', () => {
    task.completed = checkbox.checked;
    updateCounts();
  });

  const span = document.createElement('span');
  span.id = `todo-text-${task.id}`;
  span.textContent = task.text;

  const delBtn = document.createElement('button');
  delBtn.id = `todo-delete-${task.id}`;
  delBtn.textContent = 'Del';
  delBtn.setAttribute('aria-label', `Delete task "${task.text}"`);
  delBtn.addEventListener('click', () => {
    tasks = tasks.filter(t => t.id !== task.id);
    li.remove();
    updateCounts();
  });

  li.append(checkbox, span, delBtn);
  return li;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, completed: false };
  tasks.push(task);
  list.appendChild(createTaskElement(task));
  input.value = '';
  input.focus();
  updateCounts();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addTask();
});

updateCounts();
